//! Ties a moved result to an `ENGINE_REVISION` bump.
//!
//! td-bench's checksums (`harness/evals/perf-checksums.txt`) and the golden fixture
//! (`tests/fixtures/backtest_expected.json`) are both regenerated by hand after a change, and
//! neither records the revision it was made at, so a change that moves a result and forgets the
//! bump would pass CI. [`MEASURED`] records what each revision gave, and the test below fails when
//! either file no longer matches its last row.

use std::path::PathBuf;

use sha2::{Digest, Sha256};
use td_engine::ENGINE_REVISION;

/// One row per measurement, oldest first: the engine revision, td-bench's `dev` and `test`
/// checksums, and the first 16 hex digits of the golden fixture's SHA-256 (taken with `\r`
/// removed, so a Windows checkout gives the same value).
///
/// Append a row whenever either file changes; never edit a row. A change that moves a result
/// bumps `ENGINE_REVISION` and appends a row at the new revision. A change that moves only
/// td-bench's data report or loaded data, not a result, appends a row at the same revision, so
/// the diff says that no result moved. The golden fixture holds only results and the revision, so
/// a row at the same revision must keep it unchanged.
///
/// shortcut: a test cannot see edits to its own history, so a row edited in place (the last row's
/// checksums overwritten instead of a new row appended) is not caught. Upgrade with a CI step that
/// fails when `git diff origin/main -- crates/td-engine/tests/revision.rs` removes lines.
const MEASURED: &[(u32, &str, &str, &str)] = &[
    (
        7,
        "c1ad6b64d1a62ad0",
        "9bd8ed6281880a1c",
        "10e139c40d46747d",
    ),
    (
        8,
        "c1ad6b64d1a62ad0",
        "9bd8ed6281880a1c",
        "6e3ea1ae4cd6b228",
    ),
    (
        9,
        "c1ad6b64d1a62ad0",
        "9bd8ed6281880a1c",
        "59a7ed0e243197cd",
    ),
    (
        10,
        "61404601c1cd08af",
        "9bd8ed6281880a1c",
        "2476c1f429d50ad8",
    ),
];

fn repo_file(path: &str) -> String {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..");
    std::fs::read_to_string(root.join(path)).unwrap_or_else(|e| panic!("cannot read {path}: {e}"))
}

/// The checksum `perf-checksums.txt` gives `split`, read as CI's bench step reads it.
fn bench_checksum(file: &str, split: &str) -> String {
    let mut found = file
        .lines()
        .map(str::split_whitespace)
        .filter_map(|mut words| (words.next() == Some(split)).then(|| words.next()))
        .flatten();
    let checksum = found.next().unwrap_or_default().to_string();
    assert!(
        found.next().is_none(),
        "perf-checksums.txt has two {split} lines"
    );
    checksum
}

fn golden_fingerprint() -> String {
    let text =
        repo_file("crates/td-engine/tests/fixtures/backtest_expected.json").replace('\r', "");
    let hex: String = Sha256::digest(text.as_bytes())
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect();
    hex[..16].to_string()
}

#[test]
fn every_moved_result_has_a_revision_bump() {
    let &(revision, dev, test, golden) = MEASURED.last().unwrap();
    let checksums = repo_file("harness/evals/perf-checksums.txt");
    let now = (
        bench_checksum(&checksums, "dev"),
        bench_checksum(&checksums, "test"),
        golden_fingerprint(),
    );
    assert_eq!(
        (now.0.as_str(), now.1.as_str(), now.2.as_str()),
        (dev, test, golden),
        "the bench checksums or the golden fixture differ from MEASURED's last row (dev, test, \
         golden) in tests/revision.rs. If a result moved, bump ENGINE_REVISION in src/runner.rs \
         and append a row at the new revision; if only td-bench's data report or loaded data \
         moved, append a row at revision {revision}. Never edit a row."
    );
    assert_eq!(
        revision, ENGINE_REVISION,
        "MEASURED's last row is for revision {revision} but ENGINE_REVISION is {ENGINE_REVISION}: \
         append a row for the new revision"
    );
    for pair in MEASURED.windows(2) {
        let (before, after) = (pair[0], pair[1]);
        assert!(
            after.0 >= before.0,
            "MEASURED goes back from revision {} to {}",
            before.0,
            after.0
        );
        assert!(
            after.0 > before.0 || after.3 == before.3,
            "the golden fixture moved at revision {} without a bump: it holds only results",
            after.0
        );
    }
}

#[test]
fn bench_checksums_are_read_as_ci_reads_them() {
    let file = "# a comment\ndev abc\n7 dev old\ntest def\n";
    assert_eq!(bench_checksum(file, "dev"), "abc");
    assert_eq!(bench_checksum(file, "test"), "def");
    assert_eq!(bench_checksum(file, "nope"), "");
}
